def expand(scene):
    out = scene
    seen = set()
    def rep(m):
        tok = m.group(1)
        tag, name, desc = CH[tok]
        if tok in seen:
            return name
        seen.add(tok)
        return f"{name} (use the '{tag}' character sheet: {desc})"
    out = re.sub(r"\{([A-Z]+)\}", rep, out)
    out = re.sub(r"(^|[.!?] )([a-z])", lambda m: m.group(1) + m.group(2).upper(), out)
    return out

def prompt(ts, scene):
    return f"[{ts}] {expand(scene)} {STYLE}"

if __name__ == "__main__":
    here = os.path.dirname(os.path.abspath(__file__))
    with open(os.path.join(here, "ratu-kalinyamat.txt"), "w") as f:
        f.write("\n\n".join(prompt(ts, sc) for ts, _, sc in S) + "\n")
    used = sorted({CH[t][0] for _, _, sc in S for t in re.findall(r"\{([A-Z]+)\}", sc)})
    md = ["# Prompt Gambar Stickman — \"Ratu Kalinyamat\"", "",
          f"Total: **{len(S)} prompt** (1 prompt per timestamp). Rasio 16:9. Prompt dalam bahasa Inggris agar hasil model gambar lebih akurat.", "",
          "Setiap prompt merujuk ke lembar karakter dari `ratu-kalinyamat-karakter.md` (mis. *use the 'ratu' character sheet*) "
          "dan tetap menyertakan deskripsi singkat pakaiannya, jadi tiap prompt bisa berdiri sendiri.", "",
          "## Cara pakai di Google Flow", "",
          "1. Pastikan lembar karakter berikut sudah tersimpan sebagai **Ingredient** dengan nama tag-nya: "
          + ", ".join(f"`{u}`" for u in used) + ".",
          "2. Tempel instruksi agent di bawah, lalu tempel isi file `ratu-kalinyamat.txt`.",
          "3. Nama file hasil = timestamp, supaya mudah disusun di editor video.", "",
          "### Instruksi untuk agent Flow", "", "```",
          "Generate one 16:9 image for EACH prompt below, in order. Each prompt names the character sheets to use "
          "(e.g. \"use the 'ratu' character sheet\"): attach those saved Ingredients as references for that image and keep "
          "every character's face, hair, outfit, colors and props identical to their sheet. Draw any unnamed extra people "
          "as stickmen in the same style. Keep the same hand-drawn doodle art style across all images. Name each image "
          "with its timestamp (e.g. 0-00, 0-08). Do not add any text or captions.", "```", "",
          "## Daftar prompt", ""]
    for ts, nar, sc in S:
        md += [f"### {ts}", f"> {nar}", "", "```", prompt(ts, sc), "```", ""]
    with open(os.path.join(here, "ratu-kalinyamat.md"), "w") as f:
        f.write("\n".join(md))
    print(len(S), used)
